import { loadAudio } from './storage'
import { decodeAudioWindow, UnsupportedDirectDecodeError } from './direct-audio-decode'
import { sliceCapturedClip } from './capture-plan'
import { getFullSongPcmChunk, saveFullSongPcmChunk, type FullSongPcmChunkMeta } from './ai-storage'
import { applyCompactGain, copyCompactTail, crossfadeCompactHead, finishCompactSeparation } from './compact-separation'
import { separationSampleRate, stemIds, type CompactSeparationResult, type DecodedClip } from './separation'
import type { FullSongWindow } from './full-song-plan'

export interface FullSongCheckpointRequest {
  sourceImportedAt: string
  sourceDuration: number
  window: FullSongWindow
}

export interface DecodedFullSongCheckpoint {
  clip: DecodedClip
  decodeElapsedSeconds: number
}

export interface FullSongCheckpointProgress {
  phase: 'decoding' | 'loading-model' | 'separating' | 'merging'
  progress: number
}

const joinSeconds = 0.5
const joinSamples = Math.round(joinSeconds * separationSampleRate)

function checkCancelled(signal: AbortSignal): void {
  if (signal.aborted) throw new DOMException('整首分離已取消。', 'AbortError')
}

function geometry(request: FullSongCheckpointRequest) {
  const { window, sourceDuration } = request
  if (!request.sourceImportedAt || !Number.isFinite(sourceDuration) || sourceDuration <= 0 ||
    !Number.isSafeInteger(window.index) || window.index < 0 || !Number.isFinite(window.startTime) ||
    window.startTime < 0 || !Number.isFinite(window.duration) || window.duration <= 0.05 ||
    window.duration > 10.5 + 1 / separationSampleRate ||
    window.startTime + window.duration > sourceDuration + 1 / separationSampleRate ||
    (window.index === 0 && window.startTime !== 0) || (window.index > 0 && window.startTime < joinSeconds)) {
    throw new Error('測試模式的分離片段時間無效；請重新讀取已保存的進度。')
  }
  const overlap = window.index > 0 ? joinSeconds : 0
  return {
    physicalStart: window.startTime - overlap,
    captureDuration: window.duration + overlap,
    finalWindow: window.startTime + window.duration >= sourceDuration - 0.05,
  }
}

async function validateSourceAndPrevious(request: FullSongCheckpointRequest, signal: AbortSignal) {
  checkCancelled(signal)
  const source = await loadAudio()
  checkCancelled(signal)
  if (!source || source.importedAt !== request.sourceImportedAt) {
    throw new Error('來源音檔已更換；這次分離已停止，未覆寫其他歌曲的進度。')
  }
  const previous = request.window.index > 0
    ? await getFullSongPcmChunk(request.sourceImportedAt, request.window.index - 1)
    : null
  checkCancelled(signal)
  if (request.window.index > 0 && (!previous?.tail || previous.sourceImportedAt !== request.sourceImportedAt ||
    previous.captureMethod !== 'direct-file-v1' ||
    Math.abs(previous.logicalStartTime + previous.logicalDuration - request.window.startTime) > 0.02)) {
    throw new Error('找不到連續的上一段接合資料；請重新讀取已保存的進度。')
  }
  return { source, previousTail: previous?.tail }
}

/** Runs in a disposable decoder Worker. No model or WASM heap exists here. */
export async function decodeFullSongCheckpoint(
  request: FullSongCheckpointRequest,
  signal: AbortSignal,
): Promise<DecodedFullSongCheckpoint> {
  const bounds = geometry(request)
  const { source } = await validateSourceAndPrevious(request, signal)
  const startedAt = performance.now()
  let recording
  try {
    recording = await decodeAudioWindow(source.blob, source.format, bounds.physicalStart, bounds.captureDuration, signal)
  } catch (error) {
    if (error instanceof UnsupportedDirectDecodeError) {
      throw new Error(`${error.message} 此裝置不支援測試模式的背景解碼，請改用「預設模式」。`, { cause: error })
    }
    throw error
  }
  checkCancelled(signal)
  const shortfall = bounds.captureDuration - recording.duration
  if (shortfall > 0.02 && (!bounds.finalWindow || shortfall > 0.12)) {
    throw new Error('音訊解碼提早結束，尚未保存這一段；請重試。')
  }
  const clip = sliceCapturedClip(recording, { startTime: 0, duration: recording.duration })
  if (clip.left.length < 1 || clip.left.length > 11 * separationSampleRate || clip.left.length !== clip.right.length) {
    throw new Error('測試模式的音訊長度無效；這一段尚未保存。')
  }
  return { clip, decodeElapsedSeconds: (performance.now() - startedAt) / 1_000 }
}

/** Adopts inference PCM directly: a normal window never allocates a second
 * four-stem accumulator. Only a permitted final codec EOF shortfall is padded. */
export function prepareCheckpointStems(
  request: FullSongCheckpointRequest,
  stems: CompactSeparationResult,
): CompactSeparationResult {
  const bounds = geometry(request)
  const frames = stems.bass.left.length
  const targetFrames = Math.round(bounds.captureDuration * separationSampleRate)
  if (frames < 1 || stemIds.some((id) => stems[id].left.length !== frames || stems[id].right.length !== frames) ||
    frames > targetFrames || targetFrames - frames > Math.round((bounds.finalWindow ? 0.12 : 0.02) * separationSampleRate)) {
    throw new Error('AI 四軌音訊長度無效；這一段尚未保存。')
  }
  if (bounds.finalWindow && frames < targetFrames) {
    for (const id of stemIds) {
      for (const channel of ['left', 'right'] as const) {
        const padded = new Int16Array(targetFrames)
        padded.set(stems[id][channel])
        stems[id][channel] = padded
      }
    }
  }
  return stems
}

/** Runs only after the inference Worker is gone. The durable commit finishes
 * before returning metadata; no PCM buffer crosses back into the main page. */
export async function saveFullSongCheckpoint(
  request: FullSongCheckpointRequest,
  input: CompactSeparationResult,
  signal: AbortSignal,
): Promise<FullSongPcmChunkMeta> {
  const bounds = geometry(request)
  const { source, previousTail } = await validateSourceAndPrevious(request, signal)
  const stems = prepareCheckpointStems(request, input)
  const outputGain = finishCompactSeparation(stems)
  applyCompactGain(stems, outputGain)
  if (previousTail) crossfadeCompactHead(stems, previousTail, joinSamples)
  const tail = copyCompactTail(stems, joinSamples)
  checkCancelled(signal)
  return saveFullSongPcmChunk({
    sourceImportedAt: request.sourceImportedAt,
    sourceName: source.name,
    index: request.window.index,
    startTime: bounds.physicalStart,
    duration: stems.bass.left.length / separationSampleRate,
    logicalStartTime: request.window.startTime,
    logicalDuration: request.window.duration,
    sampleRate: separationSampleRate,
    captureMethod: 'direct-file-v1',
    stems,
    tail,
  })
}
