import {
  decodeFullSongCheckpoint,
  saveFullSongCheckpoint,
  type DecodedFullSongCheckpoint,
  type FullSongCheckpointRequest,
} from '../lib/full-song-checkpoint'
import type { FullSongPcmChunkMeta } from '../lib/ai-storage'
import type { CompactSeparationResult } from '../lib/separation'

export type FullSongCheckpointWorkerRequest =
  | { type: 'decode'; request: FullSongCheckpointRequest }
  | { type: 'save'; request: FullSongCheckpointRequest; stems: CompactSeparationResult }

export type FullSongCheckpointWorkerResponse =
  | ({ type: 'decoded' } & DecodedFullSongCheckpoint)
  | { type: 'saved'; chunk: FullSongPcmChunkMeta }
  | { type: 'error'; message: string }

interface WorkerScope {
  onmessage: ((event: MessageEvent<FullSongCheckpointWorkerRequest>) => void) | null
  postMessage(message: FullSongCheckpointWorkerResponse, transfer?: Transferable[]): void
}

const scope = self as unknown as WorkerScope
// Cancellation terminates the whole one-shot Worker, including active codecs.
const controller = new AbortController()
let started = false
scope.onmessage = (event) => {
  if (started) return
  started = true
  const message = event.data
  void (async () => {
    if (message.type === 'decode') {
      const decoded = await decodeFullSongCheckpoint(message.request, controller.signal)
      scope.postMessage({ type: 'decoded', ...decoded }, [decoded.clip.left.buffer, decoded.clip.right.buffer])
    } else {
      const chunk = await saveFullSongCheckpoint(message.request, message.stems, controller.signal)
      scope.postMessage({ type: 'saved', chunk })
    }
  })().catch((error: unknown) => {
    scope.postMessage({ type: 'error', message: error instanceof Error ? error.message : '背景音訊處理失敗，請改用「預設模式」。' })
  })
}
