import {
  AudioSampleSink,
  BlobSource,
  FlacInputFormat,
  Input,
  Mp3InputFormat,
  WaveInputFormat,
  type AudioSample,
} from 'mediabunny'
import type { AudioFormat } from './audio'
import type { CapturedAudio } from './capture-plan'
import { separationSampleRate } from './separation'

// This decoder only keeps one separation window in RAM. The full song stays in
// its original compressed Blob, rather than in an AudioBuffer or playback graph.
const maximumWindowSeconds = 32
const maximumGapSeconds = 0.005
// Lossy decoders need a little history before the requested first frame.
// Without it, an MP3 seek can alter the first ~50 ms of each 15-second window.
const decoderWarmupSeconds = 0.25

export class UnsupportedDirectDecodeError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'UnsupportedDirectDecodeError'
  }
}

type DecodedSample = Pick<AudioSample,
  'timestamp' | 'sampleRate' | 'numberOfFrames' | 'numberOfChannels' | 'copyTo'>

function toPcm16(value: number): number {
  const clipped = Math.max(-1, Math.min(1, value))
  return Math.round(clipped * (clipped < 0 ? 32_768 : 32_767))
}

/** Places decoded packets on the source's integer-frame timeline. Both sides
 * of a 15-second boundary therefore use the same source samples. */
export class SampleAlignedWindow {
  private readonly startFrame: number
  private readonly present: Uint8Array
  readonly left: Int16Array
  readonly right: Int16Array

  constructor(readonly sampleRate: number, startTime: number, duration: number) {
    if (!Number.isFinite(sampleRate) || sampleRate <= 0) throw new Error('音檔的取樣率無效。')
    if (!Number.isFinite(startTime) || startTime < 0 || !Number.isFinite(duration) ||
      duration <= 0 || duration > maximumWindowSeconds + decoderWarmupSeconds + 0.01) {
      throw new Error('音訊解碼片段長度無效。')
    }
    this.startFrame = Math.round(startTime * sampleRate)
    const frames = Math.round((startTime + duration) * sampleRate) - this.startFrame
    this.left = new Int16Array(frames)
    this.right = new Int16Array(frames)
    this.present = new Uint8Array(frames)
  }

  get absoluteStartFrame(): number {
    return this.startFrame
  }

  append(sample: DecodedSample): void {
    if (sample.sampleRate !== this.sampleRate) throw new Error('來源音檔的取樣率在解碼中改變。')
    if (sample.numberOfChannels < 1 || sample.numberOfFrames < 1) return
    const packetStart = Math.round(sample.timestamp * this.sampleRate)
    const first = Math.max(0, this.startFrame - packetStart)
    const last = Math.min(sample.numberOfFrames, this.startFrame + this.left.length - packetStart)
    if (last <= first) return

    const count = last - first
    const left = new Float32Array(count)
    const right = sample.numberOfChannels > 1 ? new Float32Array(count) : left
    sample.copyTo(left, { planeIndex: 0, format: 'f32-planar', frameOffset: first, frameCount: count })
    if (sample.numberOfChannels > 1) {
      sample.copyTo(right, { planeIndex: 1, format: 'f32-planar', frameOffset: first, frameCount: count })
    }
    const outputStart = packetStart + first - this.startFrame
    for (let index = 0; index < count; index += 1) {
      const output = outputStart + index
      this.left[output] = toPcm16(left[index] ?? 0)
      this.right[output] = toPcm16(right[index] ?? 0)
      this.present[output] = 1
    }
  }

  finish(): CapturedAudio {
    let length = this.present.length
    while (length > 0 && !this.present[length - 1]) length -= 1
    if (length === 0) throw new Error('音檔沒有解碼出可用的音訊。')

    // A codec's packet timestamps can be rounded by one or two frames. Bridge
    // only tiny rounding holes; a real seek/decode dropout must fail visibly.
    const allowedGap = Math.ceil(this.sampleRate * maximumGapSeconds)
    for (let index = 0; index < length;) {
      if (this.present[index]) {
        index += 1
        continue
      }
      const gapStart = index
      while (index < length && !this.present[index]) index += 1
      if (index - gapStart > allowedGap) {
        throw new Error('音檔解碼出現缺口，這一段未保存；請重新載入音檔後再試，或回報此問題。')
      }
      const before = gapStart > 0 ? gapStart - 1 : index
      const after = index < length ? index : before
      for (let frame = gapStart; frame < index; frame += 1) {
        const fraction = before === after ? 0 : (frame - before) / (after - before)
        this.left[frame] = Math.round((this.left[before] ?? 0) * (1 - fraction) + (this.left[after] ?? 0) * fraction)
        this.right[frame] = Math.round((this.right[before] ?? 0) * (1 - fraction) + (this.right[after] ?? 0) * fraction)
      }
    }
    return {
      left: this.left.subarray(0, length),
      right: this.right.subarray(0, length),
      sampleRate: this.sampleRate,
      duration: length / this.sampleRate,
    }
  }
}

/** Resample against the *song's* 44.1 kHz frame grid. Resampling against a
 * window-local zero would phase-shift overlapping windows from 48/96 kHz files. */
export function resampleAbsoluteWindow(
  native: CapturedAudio,
  nativeStartFrame: number,
  targetStartFrame: number,
  targetEndFrame: number,
): CapturedAudio {
  const targetFrames = targetEndFrame - targetStartFrame
  if (targetFrames <= 0) throw new Error('音訊解碼片段長度無效。')
  const left = new Int16Array(targetFrames)
  const right = new Int16Array(targetFrames)
  const lastNativeFrame = nativeStartFrame + Math.min(native.left.length, native.right.length) - 1
  let written = 0
  for (; written < targetFrames; written += 1) {
    const absoluteNativePosition = (targetStartFrame + written) * native.sampleRate / separationSampleRate
    if (absoluteNativePosition > lastNativeFrame + 1e-7) break
    const lower = Math.floor(absoluteNativePosition)
    const upper = Math.min(lower + 1, lastNativeFrame)
    const fraction = absoluteNativePosition - lower
    const localLower = lower - nativeStartFrame
    const localUpper = upper - nativeStartFrame
    if (localLower < 0) throw new Error('音訊解碼片段缺少起點樣本。')
    left[written] = Math.round((native.left[localLower] ?? 0) * (1 - fraction)
      + (native.left[localUpper] ?? 0) * fraction)
    right[written] = Math.round((native.right[localLower] ?? 0) * (1 - fraction)
      + (native.right[localUpper] ?? 0) * fraction)
  }
  if (written === 0) throw new Error('音檔沒有解碼出可用的音訊。')
  return {
    left: left.subarray(0, written),
    right: right.subarray(0, written),
    sampleRate: separationSampleRate,
    duration: written / separationSampleRate,
  }
}

/** Decode just one short window from the local audio Blob. This never calls
 * play(), changes currentTime, or routes any signal through the speakers. */
export async function decodeAudioWindow(
  blob: Blob,
  format: AudioFormat,
  startTime: number,
  duration: number,
  signal: AbortSignal,
): Promise<CapturedAudio> {
  if (signal.aborted) throw new DOMException('音檔解碼已取消。', 'AbortError')
  if (!Number.isFinite(startTime) || startTime < 0 || !Number.isFinite(duration) ||
    duration <= 0 || duration > maximumWindowSeconds) {
    throw new Error('音訊解碼片段長度無效。')
  }
  const input = new Input({
    source: new BlobSource(blob, { maxCacheSize: 256 * 1024 }),
    formats: [new Mp3InputFormat(), new WaveInputFormat(), new FlacInputFormat()],
  })
  const abort = () => {
    if (!input.disposed) input.dispose()
  }
  signal.addEventListener('abort', abort, { once: true })
  try {
    if (!(await input.canRead())) throw new UnsupportedDirectDecodeError(`無法直接讀取此 ${format.toUpperCase()} 音檔。`)
    const track = await input.getPrimaryAudioTrack()
    if (!track || !(await track.canDecode())) {
      throw new UnsupportedDirectDecodeError(`此裝置無法直接解碼 ${format.toUpperCase()}。`)
    }
    const sampleRate = await track.getSampleRate()
    const channels = await track.getNumberOfChannels()
    if (sampleRate > 192_000 || channels > 2) {
      // The fallback playback path can downmix unusual multichannel files;
      // do not allocate an unexpectedly huge native-rate window on iPhone.
      throw new UnsupportedDirectDecodeError('這個音檔的取樣率或聲道數超出手機直接解碼的安全範圍。')
    }
    const targetStartFrame = Math.round(startTime * separationSampleRate)
    const targetEndFrame = Math.round((startTime + duration) * separationSampleRate)
    const nativeStartFrame = Math.max(
      0,
      Math.floor(targetStartFrame * sampleRate / separationSampleRate) - Math.ceil(decoderWarmupSeconds * sampleRate) - 1,
    )
    const lastTargetPosition = (targetEndFrame - 1) * sampleRate / separationSampleRate
    const nativeExclusiveEndFrame = Math.ceil(lastTargetPosition) + 2
    const decodeStart = nativeStartFrame / sampleRate
    const decodeDuration = (nativeExclusiveEndFrame - nativeStartFrame) / sampleRate
    const window = new SampleAlignedWindow(sampleRate, decodeStart, decodeDuration)
    const sink = new AudioSampleSink(track)
    const predecessor = await sink.getSample(decodeStart)
    if (predecessor) {
      try {
        window.append(predecessor)
      } finally {
        predecessor.close()
      }
    }
    // The iterator starts from packets at/after decodeStart. getSample above
    // supplies the packet that began before that time but still overlaps it.
    for await (const sample of sink.samples(decodeStart, nativeExclusiveEndFrame / sampleRate)) {
      try {
        if (signal.aborted) throw new DOMException('音檔解碼已取消。', 'AbortError')
        window.append(sample)
      } finally {
        sample.close()
      }
    }
    return resampleAbsoluteWindow(window.finish(), window.absoluteStartFrame, targetStartFrame, targetEndFrame)
  } catch (error) {
    if (signal.aborted) throw new DOMException('音檔解碼已取消。', 'AbortError')
    throw error
  } finally {
    signal.removeEventListener('abort', abort)
    if (!input.disposed) input.dispose()
  }
}
