import { separationSampleRate, type DecodedClip } from './separation'

export interface CapturedAudio {
  left: Int16Array
  right: Int16Array
  sampleRate: number
  duration: number
}

export interface CaptureSegment {
  startTime: number
  duration: number
}

/** Copy one model-sized slice from one continuous recording. The copies can be
 * transferred to a Worker without detaching the full recording's buffers. */
export function sliceCapturedClip(
  recording: CapturedAudio,
  segment: CaptureSegment,
  targetSampleRate = separationSampleRate,
): DecodedClip {
  const sourceFrames = Math.min(recording.left.length, recording.right.length)
  const start = Math.min(Math.max(Math.round(segment.startTime * targetSampleRate), 0), Math.round(recording.duration * targetSampleRate))
  const end = Math.min(
    Math.max(Math.round((segment.startTime + segment.duration) * targetSampleRate), start),
    Math.round(recording.duration * targetSampleRate),
  )
  const left = new Float32Array(end - start)
  const right = new Float32Array(end - start)

  // Resample against the recording's absolute timeline, so the same overlap
  // sample is bit-for-bit identical in both adjacent model chunks.
  for (let index = 0; index < left.length; index += 1) {
    const sourcePosition = (start + index) * recording.sampleRate / targetSampleRate
    const lower = Math.min(Math.floor(sourcePosition), sourceFrames - 1)
    const upper = Math.min(lower + 1, sourceFrames - 1)
    const fraction = sourcePosition - lower
    left[index] = ((recording.left[lower] ?? 0) * (1 - fraction)
      + (recording.left[upper] ?? 0) * fraction) / 32_768
    right[index] = ((recording.right[lower] ?? 0) * (1 - fraction)
      + (recording.right[upper] ?? 0) * fraction) / 32_768
  }
  return { left, right, duration: left.length / targetSampleRate }
}

export function createCapturePlan(
  startTime: number,
  sourceDuration: number,
  requestedDuration: number,
  segmentDuration: number,
  overlapDuration: number,
): CaptureSegment[] {
  const available = Math.min(requestedDuration, Math.max(0, sourceDuration - startTime))
  if (available <= 0.05) return []
  const step = segmentDuration - overlapDuration
  if (step <= 0) throw new Error('片段重疊時間必須短於片段長度。')
  const segments: CaptureSegment[] = []
  for (let offset = 0; offset < available - 0.001; offset += step) {
    const duration = Math.min(segmentDuration, available - offset)
    if (duration <= 0.05) break
    if (segments.length > 0 && duration <= overlapDuration + 0.05) break
    segments.push({ startTime: startTime + offset, duration })
    if (duration < segmentDuration) break
  }
  return segments
}
